const DECIDE=[['X ≥ 10',-1,10,12],['X ≥ 10',-1,10,10],['X ≥ 10',-1,10,9],['X ≤ 2',2,99,2],['X ≤ 2',2,99,3],['X ≤ 1 or X ≥ 11',1,11,10]];
