  const i=+b.dataset.i,ok=i===it.answer;box.querySelectorAll('[data-i]').forEach(x=>{x.disabled=true;if(+x.dataset.i===it.answer)x.classList.add('ux-right');else if(x===b)x.classList.add('ux-wrong')});
